/**
 * Browser evaluator: a line-for-line port of src/backend/deaths_warrant/evaluate.py.
 * Every model's golden.json (generated by the Python reference) is replayed against this
 * file in evaluate.test.ts, so the two cannot silently drift. Change both together.
 */

import { layerInputs, type Input, type ModelSpec, type Term, type Value, type WeightedValue } from "./spec";

export const HORIZON_YEARS = 60;
const BISECTION_STEPS = 64;
const CURVE_STEP_YEARS = 0.25;
const CURVE_END_YEARS = 30;
const SURVIVAL_TIMES = [1, 3, 5] as const;

export type Observed = Record<string, Value | null | undefined>;
type SurvivalFn = (t: number) => number;
export type InputStatus = "observed" | "missing" | "implausible" | "unused";

export class EvaluationError extends Error {}

export interface EvaluationResult {
  model: string;
  model_version: string;
  layer: { id: string; label: string };
  skipped_layers: { id: string; label: string; lacking: string[] }[];
  median_years: number | null;
  range_low_years: number | null;
  range_high_years: number | null;
  survival_at: Record<string, number>;
  beyond_reliable: boolean;
  curve: [number, number][];
  inputs: { id: string; label: string; status: InputStatus; value: Value | null; assumed: WeightedValue[] | null }[];
  terms: { input: string; kind: Term["kind"]; contribution: number | null }[];
}

function plausible(i: Input, v: Value): boolean {
  if (i.type === "number") return typeof v === "number" && Number.isFinite(v) && i.min <= v && v <= i.max;
  if (i.type === "enum") return typeof v === "string" && i.values.includes(v);
  return typeof v === "boolean";
}

export function resolveInputs(spec: ModelSpec, observed: Observed) {
  const values: Record<string, Value> = {};
  const status: Record<string, InputStatus> = {};
  for (const i of spec.inputs) {
    const v = observed[i.id];
    if (v === null || v === undefined) status[i.id] = "missing";
    else if (plausible(i, v)) {
      values[i.id] = v;
      status[i.id] = "observed";
    } else status[i.id] = "implausible";
    if (!(i.id in values) && i.missing === null) {
      throw new EvaluationError(`${i.label} is required but was not found in the record`);
    }
  }
  return { values, status };
}

export function termValue(term: Term, x: Value): number {
  switch (term.kind) {
    case "linear": {
      let xf = Number(x);
      if (term.min !== null) xf = Math.max(xf, term.min);
      if (term.max !== null) xf = Math.min(xf, term.max);
      return term.coef * (xf - term.center);
    }
    case "bands": {
      for (const band of term.bands) if (band.lt === null || Number(x) < band.lt) return band.value;
      throw new Error("unreachable: last band is a catch-all");
    }
    case "category": {
      const key = typeof x === "boolean" ? (x ? "true" : "false") : String(x);
      return term.values[key]!;
    }
  }
}

export function populationCumHazard(table: number[], age: number, t: number): number {
  const end = age + t;
  let total = 0;
  let x = age;
  while (x < end) {
    const i = Math.floor(x);
    const next = Math.min(i + 1, end);
    const q = table[Math.min(i, table.length - 1)]!;
    total += -Math.log1p(-q) * (next - x);
    x = next;
  }
  return total;
}

function survivalFn(spec: ModelSpec, layerIndex: number, values: Record<string, Value>): SurvivalFn {
  const survival = spec.layers[layerIndex]!.survival;
  let lp = 0;
  for (const term of survival.terms) lp += termValue(term, values[term.input]!);
  const hr = Math.exp(lp);
  if (survival.type === "weibull_ph") {
    const { shape, scale_years: scale } = survival;
    return (t) => Math.exp(-hr * (t / scale) ** shape);
  }
  const table = spec.life_tables[survival.life_table]!;
  const q = values[survival.sex_input] === "female" ? table.female : table.male;
  const age = Number(values[survival.age_input]);
  return (t) => Math.exp(-hr * populationCumHazard(q, age, t));
}

export function solveTime(s: SurvivalFn, p: number): number | null {
  if (s(HORIZON_YEARS) > p) return null;
  let lo = 0;
  let hi = HORIZON_YEARS;
  for (let k = 0; k < BISECTION_STEPS; k++) {
    const mid = (lo + hi) / 2;
    if (s(mid) > p) lo = mid;
    else hi = mid;
  }
  return (lo + hi) / 2;
}

/** Cartesian product in itertools.product order (last list varies fastest). */
function product<T>(lists: T[][]): T[][] {
  let out: T[][] = [[]];
  for (const list of lists) out = out.flatMap((prefix) => list.map((item) => [...prefix, item]));
  return out;
}

export function evaluate(spec: ModelSpec, observed: Observed): EvaluationResult {
  const resolved = resolveInputs(spec, observed);
  const skipped: EvaluationResult["skipped_layers"] = [];
  let layerIndex = 0;
  for (; layerIndex < spec.layers.length; layerIndex++) {
    const layer = spec.layers[layerIndex]!;
    const lacking = layer.requires.filter((r) => !(r in resolved.values));
    if (!lacking.length) break;
    skipped.push({ id: layer.id, label: layer.label, lacking });
  }
  const layer = spec.layers[layerIndex]!;
  const inputs = new Map(spec.inputs.map((i) => [i.id, i]));
  const used = layerInputs(layer);
  const unknown = used.filter((n) => !(n in resolved.values));

  const fns: SurvivalFn[] = [];
  const weights: number[] = [];
  for (const combo of product(unknown.map((n) => inputs.get(n)!.missing ?? []))) {
    const values = { ...resolved.values };
    let weight = 1;
    combo.forEach((wv, k) => {
      values[unknown[k]!] = wv.value;
      weight *= wv.weight;
    });
    fns.push(survivalFn(spec, layerIndex, values));
    weights.push(weight);
  }
  let totalWeight = 0;
  for (const w of weights) totalWeight += w;

  const s: SurvivalFn = (t) => {
    let acc = 0;
    for (let k = 0; k < fns.length; k++) acc += weights[k]! * fns[k]!(t);
    return acc / totalWeight;
  };

  const median = solveTime(s, 0.5);
  const steps = Math.round(CURVE_END_YEARS / CURVE_STEP_YEARS);
  return {
    model: spec.id,
    model_version: spec.version,
    layer: { id: layer.id, label: layer.label },
    skipped_layers: skipped,
    median_years: median,
    range_low_years: solveTime(s, 0.75),
    range_high_years: solveTime(s, 0.25),
    survival_at: Object.fromEntries(SURVIVAL_TIMES.map((t) => [String(t), s(t)])),
    beyond_reliable: median === null || median > spec.max_reliable_years,
    curve: Array.from({ length: steps + 1 }, (_, k) => [k * CURVE_STEP_YEARS, s(k * CURVE_STEP_YEARS)]),
    inputs: spec.inputs.map((i) => ({
      id: i.id,
      label: i.label,
      status: used.includes(i.id) ? resolved.status[i.id]! : "unused",
      value: resolved.values[i.id] ?? null,
      assumed: unknown.includes(i.id) ? (i.missing ?? []) : null,
    })),
    terms: layer.survival.terms.map((t) => ({
      input: t.input,
      kind: t.kind,
      contribution: t.input in resolved.values ? termValue(t, resolved.values[t.input]!) : null,
    })),
  };
}
